arguments.command:
for i in 1 2 3; do curl -s "https://api.box.com/2.0/search?query=pdf&type=file" -H "Authorization: Bearer <TOKEN>"; echo; done | python3 -c "
import sys, json
seen=set()
for line in sys.stdin:
    try: d=json.loads(line)
    except: continue
    for e in d.get('entries',[]):
        if e.get('extension')=='pdf' and e['id'] not in seen:
            seen.add(e['id'])
            print(e['id'], e['name'], '| owner:', e.get('owned_by',{}).get('name'), '| modified_by:', e.get('modified_by',{}).get('name'), '| parent:', e.get('parent',{}).get('name'))
"

